import { test, expect } from '@playwright/test';

test.describe('1. Админ-панель — матрица прав и спец. действия', () => {
  test('1.11 Гость открывает /redeem-code — поле кода и кнопки @desktop @prod-safe (#6a8ffaeb9ee5a7da68ca5bc7)', async ({ page }) => {
    // 1. Открыть `/redeem-code`.
    await page.goto('/redeem-code');

    // Остаётся на /redeem-code
    await expect(page).toHaveURL(/\/redeem-code/);
    // Заголовок, поле кода, подсказка
    await expect(page.getByText(/Enter your support code|הזנת קוד מהתמיכה/)).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'A2B3-C4D5-E6F7' })).toBeVisible();
    await expect(page.getByText(/one-time|only by the team|הקוד נוצר על ידי הצוות בלבד ומשמש פעם אחת/i)).toBeVisible();
    // Кнопка «Set the password» disabled при пустом коде; есть «Back to sign in»
    await expect(page.getByRole('button', { name: /Set the password|קביעת הסיסמה/ })).toBeDisabled();
    await expect(page.getByRole('button', { name: /Back to sign in|חזרה למסך ההתחברות/ })).toBeVisible();
  });
});
